/* Poll Pilled: framework-free interface, backed by Flask + SQLite. */
'use strict';
const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {icons:{},csrf:'',polls:[],allPolls:[],view:'explore',mode:'',category:'All topics',sort:'trending',q:'',profile:{},stats:{},ai:false,room:null,roomTab:'overview',replyTo:null,takeSort:'newest',aiReply:'',modal:null,opposing:false,composer:null};
const reducedMotion=()=>!!state.preferences?.reduce_motion||window.matchMedia('(prefers-reduced-motion: reduce)').matches;
let feedController, activeAudio, activeAudioId, recording=null, recordingStream=null, recordingTimer=null, recordingSeconds=0, recordingBlob=null, recordingURL=null, recognition=null, searchTimer, lastFocus, roomRequest=0;
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${state.icons[name] || state.icons['stars-linear'] || ''}</svg>`;
function hydrateIcons(root=document){ $$('[data-icon]',root).forEach(el=>{const template=document.createElement('template');template.innerHTML=icon(el.dataset.icon);const svg=template.content.firstElementChild;if(el.id)svg.id=el.id;for(const cls of el.classList)svg.classList.add(cls);el.replaceWith(svg);}); }
function setBreadcrumb(label,name){$('#breadcrumb-current').textContent=label;const svg=$('#breadcrumb-icon');if(svg)svg.innerHTML=state.icons[name]||state.icons['home-smile-linear']||'';}
const formatNumber = n => Number(n).toLocaleString();
const compact = n => n>=1000 ? `${(n/1000).toFixed(1)}k` : String(n);
function remaining(date){const hours=Math.max(0,Math.ceil((new Date(date)-Date.now())/3600000));return hours>24?`${Math.ceil(hours/24)}d left`:hours?`${hours}h left`:'Closed';}
function ago(date){const mins=Math.max(0,Math.floor((Date.now()-new Date(date))/60000));if(!mins)return 'Just now';return mins<60?`${mins}m ago`:mins<1440?`${Math.floor(mins/60)}h ago`:`${Math.floor(mins/1440)}d ago`;}
function waveform(seed=1){return `<span class="waveform">${Array.from({length:32},(_,i)=>`<i style="--h:${7+((i*13+seed*7)%22)}px;--d:${(i%7)*.09}s"></i>`).join('')}</span>`;}
function avatar(initials,color='peach',extra=''){return `<span class="avatar ${escapeHTML(color)} ${extra}">${escapeHTML(initials)}</span>`;}
function initials(name){return name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function safeMedia(url){return typeof url==='string' && (/^\/static\//.test(url)||/^\/uploads\/[a-f0-9]{32}\.(webp|webm|ogg|wav|m4a|mp3)$/.test(url))?escapeHTML(url):'';}
async function api(path,{method='GET',data,signal}={}){
  const headers={};let body;
  if(method!=='GET'&&path!=='/api/polls/quote'&&state.security?.turnstile_enabled)headers['X-Turnstile-Token']=await securityToken();
  if(path.endsWith('/vote')&&data){const id=path.split('/')[3];data={...data,elapsed_seconds:Math.round((performance.now()-(pollStarted.get(id)||performance.now()))/1000)};}
  if(method!=='GET'){headers['X-CSRF-Token']=state.csrf;if(data instanceof FormData){body=data;}else{headers['Content-Type']='application/json';body=JSON.stringify(data||{});}}
  const response=await fetch(path,{method,headers,body,signal});
  const result=await response.json().catch(()=>({error:'The server returned an unexpected response.'}));
  if(!response.ok)throw new Error(result.error||'Something went wrong. Please try again.');
  return result;
}
function toast(message,error=false,destination=null){const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.setAttribute('role',error?'alert':'status');node.innerHTML=`${icon(error?'close-circle-linear':'check-circle-linear')}<span>${escapeHTML(message)}</span>${destination?`<button data-view="${escapeHTML(destination.view)}">${escapeHTML(destination.label)}</button>`:''}`;$('#toasts').append(node);setTimeout(()=>node.remove(),5500);}
const mobileNavigation=window.matchMedia('(max-width:800px)');
function syncNavigation(){const open=$('#sidebar').classList.contains('open');const blocking=!!state.modal&&state.modal!=='room';$('#sidebar').inert=blocking||(mobileNavigation.matches&&!open);$('.app-shell').inert=blocking;const toggle=$('[data-action="menu"]');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');}
mobileNavigation.addEventListener('change',syncNavigation);
async function refreshProfile(){const config=await api('/api/bootstrap');Object.assign(state,{categories:config.categories,csrf:config.csrf,profile:config.profile,stats:config.stats,ai:config.ai_available,market:config.marketplace,preferences:config.preferences,aiModel:config.ai_model,connections:config.ai_connections,security:config.security});$('#profile-name').textContent=state.profile.anonymous_name||state.profile.name;$$('.profile-avatar,.avatar.small').forEach(el=>el.textContent=initials(state.profile.anonymous_name||state.profile.name));$('#my-polls-count').textContent=state.stats.polls;$('#saved-count').textContent=state.stats.saved;for(const kind of ['votes','polls','saved'])$('#stat-'+kind).textContent=state.stats[kind];if(typeof marketUpdated==='function')marketUpdated();if(typeof preferencesUpdated==='function')preferencesUpdated();}
function categoryChips(){$('#category-chips').innerHTML=state.categories.map(c=>`<button class="category-chip${state.category===c?' active':''}" data-topic="${escapeHTML(c)}" aria-pressed="${state.category===c}">${escapeHTML(c)}</button>`).join('');$$('.topic-nav button').forEach(b=>b.classList.toggle('active',b.dataset.topic===state.category));}
function setView(view){
  if(['wallet','publisher','credits'].includes(view)){showMarketView(view);return;}
  if(state.modal==='room')closeModal();
  document.body.classList.remove('market-view');if(!location.pathname.startsWith('/poll/'))history.replaceState({},'','/');
  window.scrollTo({top:0});stopAudio();state.view=view;state.mode='';state.category='All topics';state.q='';$('#search').value='';$('#sidebar').classList.remove('open');
  $$('.nav-item[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
  const copy={explore:['Community','Make your voice count.','Pick a side. Tell us why. Get a little something back.','A question worth your time'],lounge:['Voice lounge','There’s a voice behind every vote.','Listen to a fresh perspective. Then take the mic and share yours.','Take the floor'],mine:['My polls','Conversations you started.','A good question can go a long way. See where yours takes people.','Your polls'],saved:['Saved polls','A little curiosity for later.','The questions and conversations you want to come back to.','Saved conversations'],voted:['Your votes','Your side of the story.','Revisit your votes, hear someone out, or change your mind.','Conversations you joined']}[view];
  setBreadcrumb(copy[0],{explore:'home-smile-linear',lounge:'microphone-3-linear',mine:'chart-square-linear',saved:'bookmark-linear',voted:'check-circle-linear'}[view]);$('#page-title').textContent=copy[1];$('#page-description').textContent=copy[2];$('#feed-title').textContent=copy[3];$('#hero').hidden=view!=='explore';$('.feed-tabs').hidden=view==='lounge';setFormatTabs();categoryChips();syncNavigation();loadFeed();
}
function setFormatTabs(){$$('.feed-tab').forEach(b=>{const active=b.dataset.format===state.mode;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});}
async function loadFeed(){
  feedController?.abort();feedController=new AbortController();
  const params=new URLSearchParams({view:state.view,category:state.category,mode:state.mode,sort:state.sort,q:state.q});
  try{const result=await api('/api/polls?'+params,{signal:feedController.signal});state.polls=result.polls;renderFeed();}catch(err){if(err.name==='AbortError')return;$('#poll-grid').innerHTML=`<div class="empty-state error-state">${icon('refresh-linear')}<h3>A small interruption.</h3><p>${escapeHTML(err.message)}</p><button class="button coral" data-action="reload">Try again</button></div>`;if($('#mobile-poll-list'))$('#mobile-poll-list').innerHTML=$('#poll-grid').innerHTML;}
}
function voteOptions(poll,inRoom=false){const voted=!!poll.my_vote;return `<div class="poll-options">${poll.options.map(o=>{const selected=poll.my_vote===o.id;const percentage=poll.total_votes?Math.round(o.votes/poll.total_votes*100):0;return `<button class="vote-option${selected?' selected':''}" data-vote="${escapeHTML(o.id)}" data-poll="${escapeHTML(poll.id)}" ${poll.closed||poll.reward?.status==='paused'?'disabled':''} aria-pressed="${selected}" aria-label="Vote ${escapeHTML(o.label)}${voted?`, ${percentage} percent`:''}">${voted?`<span class="vote-fill" style="--percentage:${percentage}%"></span>`:''}<span class="option-radio">${selected?icon('check-linear'):''}</span><span>${escapeHTML(o.label)}</span>${voted||poll.closed?`<span class="vote-percentage">${percentage}%</span>`:''}</button>`;}).join('')}</div>`;}
function visualOptions(poll){return `<div class="visual-options">${poll.options.map(o=>{const selected=poll.my_vote===o.id;const percent=poll.total_votes?Math.round(o.votes/poll.total_votes*100):0;return `<button class="visual-option${selected?' selected':''}" data-vote="${escapeHTML(o.id)}" data-poll="${escapeHTML(poll.id)}" ${poll.closed||poll.reward?.status==='paused'?'disabled':''} aria-pressed="${selected}"><img src="${safeMedia(o.image_url)}" alt="${escapeHTML(o.label)}" loading="lazy"><span class="visual-option-label"><span>${escapeHTML(o.label)}</span>${poll.my_vote||poll.closed?`<span class="vote-percentage">${percent}%</span>`:`<span class="option-radio"></span>`}</span></button>`;}).join('')}</div>`;}
function card(p,index){return `<article class="poll-card" data-card="${escapeHTML(p.id)}" style="animation-delay:${Math.min(index,5)*.04}s"><div class="poll-card-top"><div class="card-tags"><span class="tag">${escapeHTML(p.category)}</span>${p.mode==='voice'?`<span class="tag voice">${icon('microphone-3-linear')}Voice poll</span>`:p.mode==='image'?`<span class="tag visual">${icon('gallery-linear')}Visual poll</span>`:p.featured?`<span class="tag hot">${icon('fire-bold')}Hot topic</span>`:''}</div><button class="card-bookmark${p.saved?' saved':''}" data-save="${escapeHTML(p.id)}" aria-label="${p.saved?'Unsave':'Save'} poll" aria-pressed="${p.saved}">${icon('bookmark-linear')}</button></div><h3><button class="poll-title-link" data-open="${escapeHTML(p.id)}">${escapeHTML(p.title).replace(/\n/g,'<br>')}</button></h3><p class="card-description">${escapeHTML(p.description)}</p>${p.mode==='voice'?`<div class="voice-card-strip"><button class="voice-play" data-preview="${escapeHTML(p.id)}" aria-label="Listen to a sample take">${icon('play-bold')}</button>${waveform(index+3)}<span class="voice-duration">Hear a take</span></div><div class="voice-card-caption">${icon('headphones-round-linear')}${p.takes_count?'Listen to a different perspective':'The mic is open. Be the first voice.'}</div>`:''}${p.mode==='image'?visualOptions(p):voteOptions(p)}<div class="card-meta"><div class="meta-left"><span>${icon('users-group-rounded-linear')}${formatNumber(p.total_votes)} ${p.total_votes===1?'vote':'votes'}</span><i class="meta-divider"></i><button class="text-button" data-open="${escapeHTML(p.id)}">${icon('chat-round-line-linear')}${p.takes_count} ${p.takes_count===1?'take':'takes'}</button></div><span class="meta-right">${icon('clock-circle-linear')}${remaining(p.closes_at)}</span></div><div class="card-footer"><div class="card-author">${avatar(p.initials,p.color)}<span>${escapeHTML(p.author)}</span></div><button class="text-button" data-open="${escapeHTML(p.id)}">${p.mode==='voice'?'Drop a voice take':'Join the conversation'}${icon('arrow-right-up-linear')}</button></div></article>`;}
function emptyState(){let heading='A little quiet in here.',description='A good conversation starts with one good question.',asset='empty-polls',action='create',label='Create your first poll';if(state.q||state.category!=='All topics'||state.mode){heading='No takes on that. Yet.';description='Try another topic or a different search. Your next rabbit hole is out there.';asset='no-results';action='reset';label='Explore all polls';}else if(state.view==='saved'){heading='Keep a little curiosity for later.';description='Tap the bookmark on any poll. Your saved conversations will feel right at home here.';action='explore';label='Discover a conversation';}else if(state.view==='voted'){heading='Your first opinion is waiting.';description='Pick a side on a poll. This is where all your votes will come together.';action='explore';label='Find your first poll';}else if(state.view==='lounge'){heading='The mic is yours.';description='Start a voice poll and give the conversation a little more personality.';asset='voice-lounge';}return `<div class="empty-state"><img src="/static/illustrations/${asset}.svg" alt="Custom blue unDraw illustration"><h3>${heading}</h3><p>${description}</p><button class="button coral" data-action="${action}">${icon(action==='create'?'add-linear':'compass-linear')}${label}</button></div>`;}
function renderFeed(){$('#poll-grid').innerHTML=state.polls.length?state.polls.map(card).join(''):emptyState();$('#feed-end').hidden=!state.polls.length;const filter=$('#active-filter');filter.hidden=!state.q;if(state.q)filter.innerHTML=`<span>${state.polls.length} conversation${state.polls.length===1?'':'s'} for “${escapeHTML(state.q)}”</span><button data-action="clear-search">Clear search</button>`;}
async function updatePulse(){
  const {polls}=await api('/api/polls?sort=trending');state.allPolls=polls;
  $('#pulse-votes').textContent=compact(polls.reduce((n,p)=>n+p.total_votes,0));
  $('#community-polls').textContent=polls.filter(p=>!p.closed).length;
  $('#community-takes').textContent=polls.reduce((n,p)=>n+p.takes_count,0);
}
async function castVote(pollId,optionId,button){button.disabled=true;try{const {poll,earned_points}=await api(`/api/polls/${encodeURIComponent(pollId)}/vote`,{method:'POST',data:{option_id:optionId}});const existing=state.polls.find(p=>p.id===pollId);const changed=existing?.my_vote||state.room?.my_vote;state.polls=state.polls.map(p=>p.id===pollId?poll:p);const node=$(`[data-card="${pollId}"]`);if(node){const hadFocus=node.contains(document.activeElement);node.outerHTML=card(poll,state.polls.indexOf(poll));if(hadFocus&&!state.room)$(`[data-card="${pollId}"] [data-vote="${optionId}"]`)?.focus();}if(state.room?.id===pollId){const takes=state.room.takes;state.room={...poll,takes};$('.room-results').innerHTML=poll.mode==='image'?visualOptions(poll):voteOptions(poll,true);$('.room-totals').innerHTML=`<span>${icon('users-group-rounded-linear')}${formatNumber(poll.total_votes)} ${poll.total_votes===1?'vote':'votes'}</span><span>${icon('clock-circle-linear')}${remaining(poll.closes_at)}</span>`;$('.room-vote-note').innerHTML=`${icon('check-circle-linear')}Vote saved · change it anytime`;const side=$('#take-side');if(side)side.value=optionId;}
  if(earned_points)state.contributionReceipt={id:poll.id,title:poll.title,choice:poll.options.find(o=>o.id===optionId)?.label||'',points:earned_points,voice_bonus:poll.reward?.earned===200,milestone:state.market&&state.market.points<state.market.minimum_redemption&&state.market.points+earned_points>=state.market.minimum_redemption};
  toast(earned_points?`${earned_points} points added. Thanks for sharing what you think.`:changed?'Your vote is updated. Rewards are earned once per poll.':poll.reward?.reason?'Vote saved. '+poll.reward.reason+'.':'Your vote is in.',false,earned_points?{view:'wallet',label:'View wallet'}:null);await refreshProfile();updatePulse().catch(()=>{});
}catch(err){toast(err.message,true);}finally{button.disabled=false;}}
async function toggleSave(pollId,button){button.disabled=true;try{const {saved}=await api(`/api/polls/${encodeURIComponent(pollId)}/save`,{method:'POST'});state.polls.forEach(p=>{if(p.id===pollId)p.saved=saved;});$$(`[data-save="${pollId}"]`).forEach(b=>{b.classList.toggle('saved',saved);b.setAttribute('aria-pressed',saved);b.setAttribute('aria-label',saved?'Unsave poll':'Save poll');});if(state.room?.id===pollId)state.room.saved=saved;toast(saved?'A little curiosity, saved for later.':'Removed from your saved polls.');await refreshProfile();if(state.view==='saved')loadFeed();}catch(err){toast(err.message,true);}finally{button.disabled=false;}}
function stopAudio(){if(activeAudio){activeAudio.pause();activeAudio=null;}if('speechSynthesis'in window)speechSynthesis.cancel();$$('.waveform.playing').forEach(w=>w.classList.remove('playing'));$$('[data-preview]').forEach(b=>{b.innerHTML=icon('play-bold');b.setAttribute('aria-label','Listen to a sample take');});activeAudioId=null;}
async function previewTake(pollId,button){if(activeAudioId===pollId){stopAudio();return;}stopAudio();try{const {poll}=await api(`/api/polls/${encodeURIComponent(pollId)}`);const take=poll.takes.find(t=>t.audio_url)||poll.takes.find(t=>t.text);if(!take){openRoom(pollId);toast('The mic is open. Add the first take.');return;}activeAudioId=pollId;button.innerHTML=icon('pause-bold');button.setAttribute('aria-label','Pause sample take');button.closest('.voice-card-strip').querySelector('.waveform').classList.add('playing');if(take.audio_url){activeAudio=new Audio(take.audio_url);activeAudio.onended=stopAudio;activeAudio.onerror=()=>{stopAudio();toast('Could not play this clip. Open the poll to read the take.',true);};await activeAudio.play();}else if('speechSynthesis'in window){const speech=new SpeechSynthesisUtterance(take.text);speech.rate=1.02;speech.onend=stopAudio;speechSynthesis.speak(speech);toast('Reading this sample take aloud.');}else{openRoom(pollId);}}catch(err){stopAudio();toast(err.message,true);}}
function modal(content,{wide=false,type='info'}={}){
  if(!state.modal)lastFocus=document.activeElement;
  if(type==='room'){state.dialogReturnTo=null;$('#conversation-page')?.remove();document.body.classList.remove('conversation-open');}
  else if(state.modal==='room'&&state.room){state.dialogReturnTo=state.room.id;}
  state.modal=type;
  if(type==='room'){
    document.body.classList.remove('market-view');
    $('#modal-root').innerHTML='';document.body.classList.add('conversation-open');document.body.classList.remove('no-scroll');
    const page=document.createElement('section');page.id='conversation-page';page.className='conversation-page';page.tabIndex=-1;page.innerHTML=content;$('#main').append(page);syncNavigation();page.focus();window.scrollTo({top:0});return;
  }
  $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal${wide?' wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><button class="icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('close-circle-linear')}</button>${content}</section></div>`;
  document.body.classList.add('no-scroll');syncNavigation();$('.modal').focus({preventScroll:true});
}
function cleanupRecording(){if(recording&&recording.state!=='inactive'){recording.onstop=null;recording.stop();}recordingStream?.getTracks().forEach(t=>t.stop());recordingStream=null;recording=null;clearInterval(recordingTimer);recordingTimer=null;if(recordingURL)URL.revokeObjectURL(recordingURL);recordingURL=null;recordingBlob=null;recognition?.stop();recognition=null;}
function closeModal(){if(state.dialogReturnTo&&state.modal!=='room'){state.dialogReturnTo=null;$('#modal-root').innerHTML='';document.body.classList.remove('no-scroll');document.body.classList.add('conversation-open');state.modal='room';syncNavigation();$('#conversation-page')?.focus({preventScroll:true});return;}roomRequest++;cleanupRecording();$('#modal-root').innerHTML='';$('#conversation-page')?.remove();document.body.classList.remove('no-scroll','conversation-open');state.replyTo=null;state.aiReply='';$('#breadcrumb-current').textContent={explore:'Discover',lounge:'Voice lounge',mine:'My polls',saved:'Saved polls',voted:'Your votes',wallet:'My rewards',publisher:'Publisher studio',credits:'Publisher credits'}[state.view]||'Community';state.modal=null;state.room=null;state.opposing=false;syncNavigation();if(location.pathname.startsWith('/poll/'))history.replaceState({},'', '/');if(['wallet','publisher','credits'].includes(state.view)){document.body.classList.add('market-view');marketUpdated();}if(lastFocus?.isConnected)lastFocus.focus();else $('.sidebar-create').focus();}
async function openRoom(id,{push=true}={}){stopAudio();cleanupRecording();state.opposing=false;state.replyTo=null;state.aiReply='';state.roomTab='overview';const current=++roomRequest;modal(`<div class="modal-header"><div class="eyebrow">COME ON IN</div><h2 id="modal-title">A fresh perspective awaits.</h2></div><div class="modal-body form-loading"><span class="inline-spinner"></span>Opening the conversation…</div>`,{wide:true,type:'room'});try{const {poll}=await api(`/api/polls/${encodeURIComponent(id)}`);if(current!==roomRequest||state.modal!=='room')return;state.room=poll;renderRoom();if(push)history.pushState({poll:id},'', '/poll/'+encodeURIComponent(id));}catch(err){if(current===roomRequest){closeModal();toast(err.message,true);}}}
function takeHTML(t,children=''){
  return `<div class="thread-branch"><article class="thread-take" id="take-${escapeHTML(t.id)}"><div class="take-avatar-rail">${avatar(t.initials,t.color)}</div><div class="take-content"><div class="take-top"><strong>${escapeHTML(t.author)}</strong><small class="public-tagline">${escapeHTML(t.tagline||'')}</small><small>${ago(t.created_at)}</small>${t.sample?'<span class="sample-pill">Sample</span>':''}</div>${t.option_label?`<span class="take-side">${escapeHTML(t.option_label)}</span>`:''}${t.text?`<p class="take-text">${escapeHTML(t.text)}</p>`:''}${t.audio_url?`<div class="thread-audio"><audio controls preload="metadata" src="${safeMedia(t.audio_url)}" aria-label="${escapeHTML(t.author)}’s voice take"></audio><div class="audio-caption"><span>${icon('microphone-3-linear')}${t.sample?'AI-generated sample voice':'Voice take'}${t.duration&&!t.sample?` · ${Math.round(t.duration)}s`:''}</span>${!t.transcript?`<button type="button" data-transcribe="${escapeHTML(t.id)}">${icon('stars-linear')}Transcribe</button>`:''}</div></div>`:''}${t.transcript?`<details class="transcript"><summary>AI transcript</summary><p>${escapeHTML(t.transcript)}</p><small>AI can miss words. Check against the audio.</small></details>`:''}<div class="take-actions"><button class="take-like${t.liked?' liked':''}" data-like="${escapeHTML(t.id)}" aria-label="${t.liked?'Remove reaction':'React: fair point'}" aria-pressed="${!!t.liked}">${icon(t.liked?'heart-bold':'heart-linear')}<span>${t.likes||'Like'}</span></button><button data-reply="${escapeHTML(t.id)}" aria-label="Reply to ${escapeHTML(t.author)}">${icon('chat-round-line-linear')}Reply</button><button data-thread-ai="clarify" data-take-id="${escapeHTML(t.id)}">${icon('stars-linear')}AI lens</button></div><div class="take-ai-result" id="ai-${escapeHTML(t.id)}"></div></div></article>${children?`<div class="thread-replies">${children}</div>`:''}</div>`;
}
function takesMarkup(){
  let takes=state.room.takes;
  if(state.opposing&&state.room.my_vote)takes=takes.filter(t=>t.option_id&&t.option_id!==state.room.my_vote);
  const ids=new Set(takes.map(t=>t.id));
  const sort=(a,b)=>state.takeSort==='liked'?b.likes-a.likes||new Date(b.created_at)-new Date(a.created_at):new Date(b.created_at)-new Date(a.created_at);
  const branch=(t,depth=0)=>takeHTML(t,depth<6?takes.filter(c=>c.parent_id===t.id).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)).map(c=>branch(c,depth+1)).join(''):'');
  const roots=takes.filter(t=>!t.parent_id||!ids.has(t.parent_id)).sort(sort);
  return roots.length?roots.map(t=>branch(t)).join(''):`<div class="take-empty"><img src="/static/illustrations/empty-polls.svg" alt="Space for a new perspective"><h4>${state.opposing?'A fresh perspective is waiting.':'You could start something.'}</h4><p>${state.opposing?'No takes from the other side yet. Be curious and check back soon.':'Be the first to share your reasoning. A sentence or a short voice note is all it takes.'}</p></div>`;
}
function renderRoom(){
  const p=state.room;setBreadcrumb('Conversation','chat-round-line-linear');
  const count=p.takes.length;
  const content=`<div class="conversation-nav"><button data-action="close-modal">${icon('arrow-left-linear')}Back to conversations</button><button class="icon-button" data-action="share" aria-label="Copy conversation link">${icon('share-linear')}</button></div>
  <article class="thread-poll"><div class="thread-author">${avatar(p.initials,p.color)}<div><strong>${escapeHTML(p.author)}</strong><span class="public-tagline">${escapeHTML(p.tagline||'')}</span><span>${ago(p.created_at)} · Started ${p.mode==='voice'?'an audio':p.mode==='image'?'a visual':p.mode==='interactive'?'an interactive':'a classic'} poll</span></div><button class="card-bookmark${p.saved?' saved':''}" data-save="${escapeHTML(p.id)}" aria-label="${p.saved?'Unsave':'Save'} poll" aria-pressed="${p.saved}">${icon('bookmark-linear')}</button></div><div class="card-tags"><span class="tag">${escapeHTML(p.category)}</span>${p.mode==='voice'?`<span class="tag voice">${icon('microphone-3-linear')}Voice poll</span>`:p.mode==='image'?`<span class="tag visual">${icon('gallery-linear')}Visual poll</span>`:''}</div><h1 id="modal-title">${escapeHTML(p.title).replace(/\n/g,' ')}</h1>${p.description?`<details class="poll-context"><summary>Context${icon('alt-arrow-down-linear')}</summary><p class="room-description">${escapeHTML(p.description)}</p></details>`:''}<div class="room-results">${p.mode==='image'?visualOptions(p):voteOptions(p,true)}</div><p class="poll-data-note">Anonymous name · Answers and contributions are collected. <button class="text-button" data-action="data-policy">Data use</button></p><div class="room-vote-note">${icon(p.my_vote?'check-circle-linear':'shield-check-linear')}${p.closed?'Voting closed':p.my_vote?'Vote saved · change it anytime':'Vote to reveal results'}</div><div class="thread-poll-footer"><div class="room-totals"><span>${icon('users-group-rounded-linear')}${formatNumber(p.total_votes)} votes</span><span>${icon('clock-circle-linear')}${remaining(p.closes_at)}</span></div><button class="text-button" data-action="focus-take">${icon('chat-round-line-linear')}${count} perspective${count===1?'':'s'}</button></div></article>
  <section class="thread-ai-tools" aria-label="AI conversation tools"><div><span class="ai-tools-heading">${icon('stars-linear')}Explore the reasons</span><span class="ai-connection">${state.ai?'AI connected':'AI ready to connect'}</span></div><div class="ai-tool-buttons"><button data-action="recap">${icon('chart-2-linear')}${state.ai?'Summarize thread':'Community recap'}</button><button data-thread-ai="common_ground">${icon('users-group-rounded-linear')}Common ground</button><button data-thread-ai="reply">${icon('text-field-linear')}Help me reply</button></div><div id="room-recap"></div></section>
  <section class="social-composer" aria-label="Share a perspective"><div class="take-avatar-rail">${avatar(initials(state.profile.anonymous_name||state.profile.name),'blue')}</div><form class="take-composer" id="take-form"><label for="take-text">What’s your perspective?</label><div class="reply-context" id="reply-context" hidden></div><textarea id="take-text" class="textarea" maxlength="1200" placeholder="Add a thought. Ask a question. Hear someone out…" ${p.closed?'disabled':''}></textarea><div id="recording-preview"></div><div id="reply-ai-preview"></div><div class="take-vote-side"><label for="take-side">Your side:</label><select id="take-side"><option value="">Just adding a perspective</option>${p.options.map(o=>`<option value="${escapeHTML(o.id)}" ${p.my_vote===o.id?'selected':''}>${escapeHTML(o.label)}</option>`).join('')}</select></div><div class="take-composer-row"><div class="composer-media"><button class="record-button" type="button" data-action="record" ${p.closed?'disabled':''}>${icon('microphone-3-linear')}<span>Voice take</span></button><button class="icon-button" type="button" data-thread-ai="reply" aria-label="AI help writing your take">${icon('stars-linear')}</button></div><button class="button coral" type="submit" ${p.closed?'disabled':''}>Post perspective${icon('arrow-right-linear')}</button></div><div class="record-note">Up to 60 seconds. Listen before posting. <label class="audio-upload-label">Upload audio<input type="file" id="audio-upload" accept="audio/*" hidden></label></div><div id="take-error" role="alert"></div></form></section>
  <section class="social-discussion" aria-label="Perspectives"><div class="discussion-toolbar"><h2>Perspectives <span>${count}</span></h2><select id="take-sort" aria-label="Sort perspectives"><option value="newest" ${state.takeSort==='newest'?'selected':''}>Newest</option><option value="liked" ${state.takeSort==='liked'?'selected':''}>Most liked</option></select></div><button class="other-perspectives${state.opposing?' active':''}" data-action="opposing" aria-pressed="${state.opposing}">${icon('headphones-round-linear')}${state.opposing?'Show all perspectives':'Hear the other side'}</button><div class="takes-list social-takes" id="takes-list">${takesMarkup()}</div></section>${p.sample?'<p class="thread-sample-note">Sample poll · example counts and synthetic voices.</p>':''}`;
  $('#conversation-page').innerHTML=content;
}
function startReply(id){
  const t=state.room.takes.find(t=>t.id===id);if(!t)return;
  state.replyTo=t;const context=$('#reply-context');context.hidden=false;context.innerHTML=`<span>Replying to <strong>${escapeHTML(t.author)}</strong></span><button type="button" data-action="cancel-reply" aria-label="Cancel reply">${icon('close-circle-linear')}</button>`;$('#take-text').focus();$('#take-form').scrollIntoView({block:'center',behavior:reducedMotion()?'auto':'smooth'});
}
async function threadAI(task,takeId=null,button=null){
  const pollId=state.room?.id;if(!pollId)return;
  const target=task==='reply'?$('#reply-ai-preview'):takeId?$('#ai-'+takeId):$('#room-recap');
  if(!state.ai){target.innerHTML=`<div class="ai-inline-note">${icon('stars-linear')}Connect an AI model to use ${task==='reply'?'reply suggestions':task==='common_ground'?'common ground':task==='transcribe'?'voice transcription':'AI explanations'}. Your conversation works without it. <button class="text-button" data-meta-action="connections">Connect Meta</button></div>`;target.scrollIntoView({block:'nearest',behavior:reducedMotion()?'auto':'smooth'});return;}
  if(task==='reply'&&$('#take-text').value.trim()&&state.replyTo===null){/* The user's draft is always passed as context, never silently replaced. */}
  if(button)button.disabled=true;target.innerHTML='<div class="summary-box"><span class="inline-spinner"></span> Thinking through the conversation…</div>';
  try{
    const result=await api('/api/ai',{method:'POST',data:{task,poll_id:pollId,take_id:takeId||state.replyTo?.id||null,prompt:task==='reply'?$('#take-text').value:''}});
    if(state.room?.id!==pollId||!target.isConnected)return;
    if(task==='reply'){state.aiReply=result.summary;target.innerHTML=`<div class="ai-reply-draft"><span>${icon('stars-linear')}Suggested wording · review before posting</span><p>${escapeHTML(result.summary)}</p><button class="assist-button" type="button" data-action="use-ai-reply">Use this draft</button><button class="subtle-button" type="button" data-action="dismiss-ai-reply">Dismiss</button></div>`;}
    else if(task==='transcribe'){const {poll}=await api('/api/polls/'+pollId);if(state.room?.id===pollId){state.room=poll;$('#takes-list').innerHTML=takesMarkup();toast('Transcript ready. AI can miss words; check the audio.');}}
    else target.innerHTML=`<div class="summary-box"><strong>${icon('stars-linear')}${task==='common_ground'?'Possible common ground':'AI lens'}</strong><p>${escapeHTML(result.summary)}</p><small>AI may miss nuance. Read the original perspectives too.</small></div>`;
  }catch(err){if(target.isConnected)target.innerHTML=`<div class="form-error">${escapeHTML(err.message)}</div>`;}
  finally{if(button?.isConnected)button.disabled=false;}
}
function errorIn(id,message){const node=$(id);if(node){node.innerHTML=`<div class="form-error">${escapeHTML(message)}</div>`;node.scrollIntoView({block:'nearest',behavior:reducedMotion()?'auto':'smooth'});}}
async function toggleRecording(){
 if(recording?.state==='recording'){recording.stop();return;}
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('This browser cannot record audio. Use “upload audio” or write your take.',true);return;}
 try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(state.modal!=='room'){stream.getTracks().forEach(t=>t.stop());return;}recordingStream=stream;const types=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'];const mimeType=types.find(t=>MediaRecorder.isTypeSupported(t));recording=new MediaRecorder(stream,mimeType?{mimeType}:{});const chunks=[];recordingSeconds=0;recording.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recording.onstop=()=>{clearInterval(recordingTimer);recordingStream?.getTracks().forEach(t=>t.stop());recordingBlob=new Blob(chunks,{type:recording.mimeType});showRecordingPreview();const b=$('[data-action="record"]');if(b){b.classList.remove('recording');b.innerHTML=`${icon('microphone-3-linear')}<span>Record again</span>`;}recording=null;};recording.start();const b=$('[data-action="record"]');b.classList.add('recording');b.innerHTML=`${icon('stop-bold')}<span>Stop · 0:00</span>`;recordingTimer=setInterval(()=>{recordingSeconds++;const label=$('[data-action="record"] span');if(label)label.textContent=`Stop · ${Math.floor(recordingSeconds/60)}:${String(recordingSeconds%60).padStart(2,'0')}`;if(recordingSeconds>=60&&recording?.state==='recording')recording.stop();},1000);}catch(err){toast(err.name==='NotAllowedError'?'Microphone access is off. Allow it in your browser, or upload an audio file.':'Could not access your microphone. Try uploading an audio file.',true);}}
function showRecordingPreview(){if(recordingURL)URL.revokeObjectURL(recordingURL);recordingURL=URL.createObjectURL(recordingBlob);$('#recording-preview').innerHTML=`<div class="recording-preview"><audio src="${recordingURL}" controls aria-label="Review your recording"></audio><button class="icon-button" type="button" data-action="remove-recording" aria-label="Remove recording">${icon('trash-bin-trash-linear')}</button></div>`;}
async function submitTake(form){const button=$('button[type="submit"]',form);const text=$('#take-text').value.trim();if(recording?.state==='recording'){toast('Stop and review your recording before sharing.');return;}if(!text&&!recordingBlob){errorIn('#take-error','Give us a little context. Write a take or record your voice.');return;}button.disabled=true;button.innerHTML='<span class="inline-spinner"></span>Sharing…';try{let audio_url='';if(recordingBlob){const data=new FormData();data.append('file',recordingBlob,'take');data.append('kind','audio');audio_url=(await api('/api/upload',{method:'POST',data})).url;}const rewardResult=await api(`/api/polls/${state.room.id}/takes`,{method:'POST',data:{text,audio_url,duration:recordingSeconds,option_id:$('#take-side').value||null,parent_id:state.replyTo?.id||null}});cleanupRecording();const {poll}=await api(`/api/polls/${state.room.id}`);state.room=poll;state.replyTo=null;state.aiReply='';renderRoom();toast(rewardResult.earned_points?`+${rewardResult.earned_points} voice points! Your perspective is posted.`:'Your perspective is posted. Thanks for explaining your answer.');await refreshProfile();loadFeed();}catch(err){errorIn('#take-error',err.message);button.disabled=false;button.innerHTML=`Post perspective${icon('arrow-right-linear')}`;}}
const starterIdeas=[{title:'Would you trade a bigger salary for a shorter workweek?',description:'More time or more money? There’s no universal answer.',options:['Give me my time back','I’m taking the paycheck'],category:'Work & life'},{title:'Should AI-generated art have its own category?',description:'A question for creators, collectors, and curious humans.',options:['Yes, transparency matters','Art is art'],category:'Tech & AI'},{title:'Is it okay to leave a party without saying goodbye?',description:'The quiet exit has entered the chat.',options:['An art form, honestly','At least find the host'],category:'Culture'},{title:'Your perfect Sunday: a plan or absolutely no plans?',description:'A small question with surprisingly strong feelings.',options:['Book the brunch','Let the day happen'],category:'Work & life'}];let starterIndex=0;
function openComposer(mode='text',draft=null){cleanupRecording();state.composer=draft||{title:'',description:'',options:['',''],images:['',''],category:'Culture',hours:24,mode};modal(composerHTML(),{type:'create'});setTimeout(()=>$('#poll-question')?.focus({preventScroll:true}),100);}
function gatherComposer(){if(!$('#create-form'))return;state.composer={...state.composer,title:$('#poll-question').value,description:$('#poll-description').value,options:$$('.choice-input').map(x=>x.value),category:$('#poll-category').value,hours:Number($('#poll-duration').value)};}
function composerHTML(){const c=state.composer;return `<div class="modal-header"><h2 id="modal-title">Ask your community</h2></div><div class="modal-body"><form id="create-form"><div class="format-picker">${[['text','chart-square-linear','Classic poll','Vote with text choices.'],['voice','microphone-3-linear','Audio poll','Invite spoken reasons.'],['image','gallery-linear','Visual poll','Compare two images.'],['interactive','tuning-2-linear','Interactive','Slide to choose.']].map(([type,ico,title,desc])=>`<button type="button" class="format-choice${c.mode===type?' active':''}" data-compose-mode="${type}" aria-pressed="${c.mode===type}">${icon(ico)}<strong>${title}</strong></button>`).join('')}</div>${c.mode==='voice'?'<div class="info-box">Voters can add a voice note after answering.</div>':''}<div class="form-group"><label class="form-label" for="poll-question">Your question<small>8–180 characters</small></label><textarea id="poll-question" class="textarea question-input" maxlength="180" minlength="8" required placeholder="What do you want to learn?">${escapeHTML(c.title)}</textarea></div><div class="composer-assists"><button type="button" class="assist-button" data-action="spark">${icon('bolt-linear')}Spark an idea</button><button type="button" class="assist-button" data-action="dictate">${icon('microphone-3-linear')}Say your question</button><button type="button" class="assist-button" data-action="rephrase">${icon('text-field-linear')}Rephrase</button><button type="button" class="assist-button" data-action="studio">${icon('stars-linear')}AI assist</button></div><details class="poll-context composer-context" ${c.description?'open':''}><summary>Add context <span class="optional-hint">Optional</span>${icon('alt-arrow-down-linear')}</summary><label class="sr-only" for="poll-description">Poll context</label><textarea id="poll-description" class="textarea" rows="2" maxlength="600" placeholder="What should people know?">${escapeHTML(c.description)}</textarea></details><div class="form-group"><div class="form-label">Choices<small>2–4 options</small></div><div id="choice-inputs">${c.options.map((o,i)=>`<div class="option-input-row"><span class="option-letter">${String.fromCharCode(65+i)}</span><input class="input choice-input" value="${escapeHTML(o)}" maxlength="100" required placeholder="${i===0?'One side of the story':'A different perspective'}" aria-label="Choice ${i+1}">${c.mode==='image'?`<label class="option-image-input">${c.images?.[i]?`<img src="${safeMedia(c.images[i])}" alt="Choice ${i+1} preview">`:`${icon('gallery-linear')} Add image`}<input type="file" accept="image/png,image/jpeg,image/webp" data-choice-image="${i}" hidden></label>`:''}${c.options.length>2?`<button type="button" class="icon-button" data-remove-option="${i}" aria-label="Remove choice ${i+1}">${icon('close-circle-linear')}</button>`:''}</div>`).join('')}</div>${c.options.length<4?`<button type="button" class="add-option" data-action="add-option">${icon('add-linear')}Add another choice</button>`:''}</div><div class="form-row"><div class="form-group"><label class="form-label" for="poll-category">Topic</label><select id="poll-category" class="select">${state.categories.slice(1).map(cat=>`<option ${c.category===cat?'selected':''}>${escapeHTML(cat)}</option>`).join('')}</select></div><div class="form-group"><label class="form-label" for="poll-duration">Closes in</label><select id="poll-duration" class="select">${[[6,'6 hours'],[24,'24 hours'],[48,'2 days'],[72,'3 days'],[168,'1 week']].map(([v,l])=>`<option value="${v}" ${Number(c.hours)===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div id="create-error" role="alert"></div><div class="form-footer"><button class="button coral" type="submit">Publish your poll${icon('arrow-right-linear')}</button></div></form></div>`;}
function rerenderComposer(){const currentFocus=document.activeElement?.id;$('.modal').innerHTML=`<button class="icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('close-circle-linear')}</button>${composerHTML()}`;if(currentFocus)$('#'+currentFocus)?.focus();}
async function publishPoll(form){gatherComposer();const button=$('button[type="submit"]',form);button.disabled=true;button.innerHTML='<span class="inline-spinner"></span>Starting something…';try{const {poll}=await api('/api/polls',{method:'POST',data:state.composer});closeModal();setView('mine');await refreshProfile();toast('Your poll is live. Let the conversation begin.');openRoom(poll.id);}catch(err){errorIn('#create-error',err.message);button.disabled=false;button.innerHTML=`Publish your poll${icon('arrow-right-linear')}`;}}
function startDictation(){recordMeta('dictate');}
function openStudio(){if(!state.composer)state.composer={title:'',description:'',options:['',''],images:['',''],category:'Culture',hours:24,mode:'text'};gatherComposer();const current=state.composer;modal(`<div class="modal-header"><div class="eyebrow">THE POLL STUDIO</div><h2 id="modal-title" class="studio-title">A little help finding the question.</h2><p>Bring a messy idea. Leave with a conversation starter.</p></div><div class="modal-body"><div class="ai-status${state.ai?'':' unavailable'}"><span class="live-dot"></span>${state.ai?'Meta connected · AI-assisted drafting':'Model connection needed'}</div>${state.ai?'':`<div class="info-box">AI drafting isn’t connected yet. Try a question from the prompt library, then add your own twist.</div>`}<form id="studio-form"><div class="form-group"><label class="form-label" for="studio-prompt">The idea, dilemma, or late-night thought</label><textarea class="textarea" id="studio-prompt" maxlength="2000" placeholder="My friends can’t agree on whether a group trip needs an itinerary…" required>${escapeHTML(current?.title||'')}</textarea></div><div id="studio-error" role="alert"></div><div class="form-footer"><button type="button" class="subtle-button" data-action="back-composer">Back to your poll</button><button type="submit" class="button coral" ${state.ai?'':'disabled'}>${icon('stars-linear')}Find the question</button></div></form><button class="assist-button" data-action="library" style="margin-top:17px">${icon('bolt-linear')}Explore the prompt library</button></div>`,{type:'studio'});}
async function submitStudio(form){const button=$('button[type="submit"]',form);button.disabled=true;button.innerHTML='<span class="inline-spinner"></span>Finding the question…';try{const {draft}=await api('/api/ai',{method:'POST',data:{task:'draft',prompt:$('#studio-prompt').value}});if(!form.isConnected)return;const c={...state.composer,...draft,mode:state.composer?.mode||'text',images:[],hours:state.composer?.hours||24};if(!state.categories.includes(c.category))c.category='Culture';openComposer(c.mode,c);toast('A first draft. Make it yours before publishing.');}catch(err){errorIn('#studio-error',err.message);button.disabled=false;button.innerHTML=`${icon('stars-linear')}Find the question`;}}
function openSettings(){setView('settings');}
function openInfo(kind){if(kind==='privacy'){openSettings('privacy');return;}let title,content,kicker='A FEW THINGS WORTH KNOWING';if(kind==='help'){title='Using Poll Pilled';content=`<p>Answer funded polls, earn points, and share the reasons behind your vote.</p><div class="how-step"><span>01</span><div><strong>Pick a side.</strong><p>Vote to reveal the results. Your answer counts once, and you can change it whenever you learn something new.</p></div></div><div class="how-step"><span>02</span><div><strong>Drop a take.</strong><p>Write your reasoning or record up to 60 seconds. Review your recording, then share it with the conversation.</p></div></div><div class="how-step"><span>03</span><div><strong>Hear someone out.</strong><p>Play a voice note. Explore the other side. A fresh perspective is always welcome here.</p></div></div><h3>Your own little playground</h3><p>The initial feed is a sample community, with example votes and synthetic sample voices. Your own polls, votes, and takes are stored in Flask’s SQLite database.</p>`;}else{title='Good things, good credits.';content='<h3>Solar SVG icons</h3><p>Original icon designs by <a href="https://www.figma.com/@480design" target="_blank" rel="noopener noreferrer">480 Design</a>, used under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. Served locally as SVGs.</p><h3>Custom-colored unDraw illustrations</h3><p>Empty states and the voice lounge illustration are by <a href="https://undraw.co" target="_blank" rel="noopener noreferrer">Katerina Limpitsouni / unDraw</a>, customized with Poll Pilled’s blue accent. Used under the <a href="https://undraw.co/license" target="_blank" rel="noopener noreferrer">unDraw license</a>.</p><h3>Made with</h3><p>Python, Flask, SQLite, a little browser magic, and a healthy respect for a good question. Inter keeps the interface clear and readable. Fonts and Solar icons are served locally.</p>';}
modal(`<div class="modal-header"><div class="eyebrow">${kicker}</div><h2 id="modal-title">${title}</h2></div><div class="modal-body info-content">${content}<button class="button coral" data-action="close-modal" style="margin-top:15px">Back to the conversation${icon('arrow-right-linear')}</button></div>`);}
function openActivity(){const s=state.stats;modal(`<div class="modal-header"><div class="eyebrow">A LITTLE LOOK BACK</div><h2 id="modal-title">You’re part of the conversation.</h2><p>Every opinion starts somewhere. Here’s your footprint.</p></div><div class="modal-body"><div class="activity-stats">${[['votes','Votes cast'],['polls','Conversations started'],['takes','Takes shared'],['saved','Saved for later']].map(([key,label])=>`<div class="activity-stat"><strong>${s[key]||0}</strong><span>${label}</span></div>`).join('')}</div><p class="muted-paragraph">Your activity is remembered in this browser’s personal space. Keep exploring. There’s always another side to hear.</p><button class="button coral" data-action="close-modal" style="margin-top:12px">Keep being curious${icon('arrow-right-linear')}</button></div>`);}
async function recap(){const p=state.room;const target=$('#room-recap');target.innerHTML='<div class="summary-box"><span class="inline-spinner"></span> Gathering perspectives…</div>';try{let summary;if(state.ai){summary=(await api('/api/ai',{method:'POST',data:{task:'summary',poll_id:p.id}})).summary;}else{const ranked=[...p.options].sort((a,b)=>b.votes-a.votes);if(!p.total_votes){summary='This conversation is just getting started. Cast the first vote, then drop a take to give everyone a little context.';}else{const leader=ranked[0];const percent=Math.round(leader.votes/p.total_votes*100);summary=`“${leader.label}” leads with ${percent}% of ${formatNumber(p.total_votes)} ${p.total_votes===1?'vote':'votes'}. ${p.takes.length?`${p.takes.length} shared take${p.takes.length===1?' offers':'s offer'} a closer look at the reasons behind the votes.`:'The reasons behind the votes are still an open conversation.'} ${p.sample?'These counts include the sample community.':''}`;}}if(state.room?.id===p.id&&target.isConnected)target.innerHTML=`<div class="summary-box"><strong>${icon('stars-linear')}${state.ai?'AI-assisted recap':'A look at the numbers'}</strong><p>${escapeHTML(summary)}</p></div>`;}catch(err){if(target.isConnected)target.innerHTML=`<div class="form-error">${escapeHTML(err.message)}</div>`;}}
async function sharePoll(){const p=state.room;if(!p)return;const url=location.origin+'/poll/'+p.id;try{await navigator.clipboard.writeText(url);toast('Poll link copied. Bring a fresh perspective.');}catch{const copy=document.createElement('input');copy.value=url;$('.thread-poll-footer').after(copy);copy.className='input';copy.select();toast('Select and copy this poll link.');}}
function resetFeed(){state.category='All topics';state.mode='';state.q='';$('#search').value='';setFormatTabs();categoryChips();syncNavigation();loadFeed();}
function openWorkspace(){openAppMenu($('.brand'),true);}
async function action(name,button){switch(name){case'workspace':openWorkspace();break;case'choose-publish':closeModal();openComposer();break;case'focus-take':$('#take-text').focus();$('#take-form').scrollIntoView({block:'center',behavior:reducedMotion()?'auto':'smooth'});break;case'cancel-reply':state.replyTo=null;$('#reply-context').hidden=true;break;case'use-ai-reply':$('#take-text').value=state.aiReply;$('#reply-ai-preview').innerHTML='';$('#take-text').focus();break;case'dismiss-ai-reply':$('#reply-ai-preview').innerHTML='';state.aiReply='';break;case'all-polls':setView('explore');$('.feed-section').scrollIntoView({block:'start',behavior:reducedMotion()?'auto':'smooth'});break;case'collapse-nav':document.body.classList.toggle('nav-collapsed');button.setAttribute('aria-label',document.body.classList.contains('nav-collapsed')?'Expand sidebar':'Collapse sidebar');break;case'create':openComposer(state.view==='lounge'?'voice':state.mode||'text');break;case'close-modal':closeModal();break;case'explore':closeModal();setView('explore');break;case'menu':$('#sidebar').classList.toggle('open');syncNavigation();break;case'settings':openSettings();break;case'help':case'privacy':case'credits':openInfo(name);break;case'activity':openActivity();break;case'reset':resetFeed();break;case'reload':if(!state.csrf)location.reload();else loadFeed();break;case'clear-search':state.q='';$('#search').value='';loadFeed();break;case'add-option':gatherComposer();state.composer.options.push('');state.composer.images.push('');rerenderComposer();break;case'spark':gatherComposer();Object.assign(state.composer,starterIdeas[starterIndex++%starterIdeas.length],{images:['','']});rerenderComposer();toast('A spark from the prompt library. Make it yours.');break;case'dictate':startDictation();break;case'studio':openStudio();break;case'back-composer':openComposer(state.composer.mode,state.composer);break;case'library':{const draft={...state.composer,...starterIdeas[starterIndex++%starterIdeas.length],images:['','']};openComposer(draft.mode,draft);break;}case'record':await toggleRecording();break;case'remove-recording':cleanupRecording();$('#recording-preview').innerHTML='';break;case'share':sharePoll();break;case'recap':recap();break;case'opposing':if(!state.room.my_vote){toast('Pick a side first. Then we’ll find a different perspective.');return;}state.opposing=!state.opposing;button.innerHTML=`${icon('headphones-round-linear')}${state.opposing?'Show all perspectives':'Hear the other side'}`;button.setAttribute('aria-pressed',String(state.opposing));button.classList.toggle('active',state.opposing);$('#takes-list').innerHTML=takesMarkup();break;}}
document.addEventListener('click',async event=>{const button=event.target.closest('button,a');if(event.target.classList.contains('modal-backdrop')){closeModal();return;}if(!button){if($('#sidebar').classList.contains('open')&&!event.target.closest('#sidebar')){$('#sidebar').classList.remove('open');syncNavigation();}return;}if(button.dataset.action){event.preventDefault();action(button.dataset.action,button);return;}if(button.dataset.view){if(state.modal)closeModal();setView(button.dataset.view);return;}if(button.dataset.topic){if(state.view!=='explore'&&state.view!=='lounge')setView('explore');state.category=button.dataset.topic;categoryChips();loadFeed();$('#sidebar').classList.remove('open');syncNavigation();return;}if(button.hasAttribute('data-format')){state.mode=button.dataset.format;setFormatTabs();loadFeed();return;}if(button.dataset.reply){startReply(button.dataset.reply);return;}if(button.dataset.threadAi){threadAI(button.dataset.threadAi,button.dataset.takeId||null,button);return;}if(button.dataset.transcribe){const note=$('#ai-'+button.dataset.transcribe);note.innerHTML=`<div class="transcription-consent"><p>Transcription sends this voice clip to the connected AI provider.</p><button type="button" class="assist-button" data-confirm-transcribe="${escapeHTML(button.dataset.transcribe)}">Transcribe this clip</button></div>`;return;}if(button.dataset.confirmTranscribe){threadAI('transcribe',button.dataset.confirmTranscribe,button);return;}if(button.dataset.roomMove){const index=state.allPolls.findIndex(p=>p.id===state.room?.id);const next=state.allPolls[index+Number(button.dataset.roomMove)];if(next)openRoom(next.id);return;}if(button.hasAttribute('data-starter')){const idea=starterIdeas[Number(button.dataset.starter)];$('#quick-question').value=idea.title;$('#quick-question').focus();return;}if(button.dataset.open){openRoom(button.dataset.open);return;}if(button.dataset.vote){castVote(button.dataset.poll,button.dataset.vote,button);return;}if(button.dataset.save){toggleSave(button.dataset.save,button);return;}if(button.dataset.preview){previewTake(button.dataset.preview,button);return;}if(button.dataset.composeMode){gatherComposer();state.composer.mode=button.dataset.composeMode;rerenderComposer();return;}if(button.hasAttribute('data-remove-option')){gatherComposer();const index=Number(button.dataset.removeOption);state.composer.options.splice(index,1);state.composer.images.splice(index,1);rerenderComposer();return;}if(button.dataset.like){try{await api(`/api/takes/${encodeURIComponent(button.dataset.like)}/like`,{method:'POST'});const {poll}=await api(`/api/polls/${state.room.id}`);state.room=poll;$('#takes-list').innerHTML=takesMarkup();}catch(err){toast(err.message,true);}return;}});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='quick-create-form'){openComposer('text',{title:$('#quick-question').value.trim(),description:'',options:['',''],images:['',''],category:'Culture',hours:24,mode:'text'});}if(form.id==='create-form')publishPoll(form);if(form.id==='take-form')submitTake(form);if(form.id==='studio-form')submitStudio(form);});
document.addEventListener('change',async event=>{if(event.target.id==='take-sort'){state.takeSort=event.target.value;$('#takes-list').innerHTML=takesMarkup();}if(event.target.id==='sort'){state.sort=event.target.value;loadFeed();}if(event.target.hasAttribute('data-choice-image')){const file=event.target.files[0];if(!file)return;gatherComposer();const index=Number(event.target.dataset.choiceImage);const label=event.target.parentElement;label.style.opacity='.5';try{const data=new FormData();data.append('file',file);data.append('kind','image');const {url}=await api('/api/upload',{method:'POST',data});state.composer.images[index]=url;rerenderComposer();}catch(err){toast(err.message,true);label.style.opacity='1';}}if(event.target.id==='audio-upload'){const file=event.target.files[0];if(!file)return;if(file.size>12*1024*1024){toast('Keep your audio under 12 MB.',true);return;}cleanupRecording();recordingBlob=file;recordingSeconds=0;showRecordingPreview();toast('Audio ready. Give it a listen before sharing.');}});
$('#search').addEventListener('input',event=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.q=event.target.value.trim();loadFeed();},250);});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(state.modal)closeModal();else{$('#sidebar').classList.remove('open');syncNavigation();}}const typing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName);if(!typing&&(!state.modal||state.modal==='room')&&!event.metaKey&&!event.ctrlKey&&!event.altKey){if(event.key==='/'){event.preventDefault();document.body.classList.remove('nav-collapsed');if(mobileNavigation.matches)$('#sidebar').classList.add('open');syncNavigation();$('#search').focus();}if(event.key.toLowerCase()==='c'){event.preventDefault();openComposer();}}if(event.key==='Tab'&&state.modal&&state.modal!=='room'){const nodes=$$('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),audio[controls],[tabindex="0"]',$('.modal')).filter(n=>n.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('popstate',()=>{if(location.pathname.startsWith('/poll/'))openRoom(location.pathname.split('/').pop(),{push:false});else if(state.modal)closeModal();});
window.addEventListener('beforeunload',()=>{cleanupRecording();stopAudio();});
(async function init(){try{state.icons=await fetch('/static/icons/catalog.json').then(r=>r.json());hydrateIcons();syncNavigation();await refreshProfile();categoryChips();await Promise.all([loadFeed(),updatePulse()]);$('#year').textContent=new Date().getFullYear();if(location.pathname.startsWith('/poll/'))openRoom(location.pathname.split('/').pop(),{push:false});}catch(err){$('#poll-grid').innerHTML=`<div class="empty-state"><h3>A small interruption.</h3><p>${escapeHTML(err.message)}</p><button class="button coral" data-action="reload">Try again</button></div>`;}finally{document.body.classList.remove('app-loading');document.body.removeAttribute('aria-busy');$('#workspace-loading')?.remove();}})();

document.addEventListener('keydown',event=>{
  if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
  const active=document.activeElement;
  if(active?.getAttribute('role')!=='tab')return;
  const tabs=$$('[role="tab"]',active.closest('[role="tablist"]'));
  let next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(tabs.indexOf(active)+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;
  event.preventDefault();tabs[next].click();tabs[next].focus();
});
